using System.Security.Cryptography;using System.Text;namespace QuantForge.Core;public sealed record AndroidResearchExportItem(string Kind,string FileName,string Sha256,long Bytes);public sealed record AndroidResearchExportIndex(string Fingerprint,string JobId,IReadOnlyList<AndroidResearchExportItem> Items);public static class AndroidResearchExportIndexRules{public static AndroidResearchExportIndex Create(string jobId,IEnumerable<AndroidResearchExportItem> items){if(string.IsNullOrWhiteSpace(jobId))throw new InvalidOperationException("Research export index requires job identity.");var a=items.OrderBy(x=>x.Kind,StringComparer.Ordinal).ThenBy(x=>x.FileName,StringComparer.Ordinal).ToArray();if(a.Length==0)throw new InvalidOperationException("Research export index requires at least one artifact.");if(a.Any(x=>string.IsNullOrWhiteSpace(x.Kind)||string.IsNullOrWhiteSpace(x.FileName)||string.IsNullOrWhiteSpace(x.Sha256)||x.Bytes<0))throw new InvalidOperationException("Research export artifact identity is incomplete.");var text=jobId+"|"+string.Join("|",a.Select(x=>$"{x.Kind}:{x.FileName}:{x.Sha256}:{x.Bytes}"));var fp=Convert.ToHexString(SHA256.HashData(Encoding.UTF8.GetBytes(text)));return new(fp,jobId,a);}}
